import { createServer as createHttpServer } from "node:http";
import type { IncomingMessage, Server, ServerResponse } from "node:http";
import { NoteStore } from "./noteStore.ts";

type Logger = (line: string) => void;

function send(res: ServerResponse, status: number, payload: unknown): void {
  res.writeHead(status, { "content-type": "application/json" });
  res.end(JSON.stringify(payload));
}

const fail = (res: ServerResponse, status: number, error: string) => send(res, status, { error });

async function readBody(req: IncomingMessage): Promise<string> {
  const chunks: Buffer[] = [];
  for await (const chunk of req) chunks.push(chunk as Buffer);
  return Buffer.concat(chunks).toString("utf8");
}

function parseObject(raw: string): Record<string, unknown> | undefined {
  try {
    const value: unknown = JSON.parse(raw);
    if (typeof value === "object" && value !== null && !Array.isArray(value)) {
      return value as Record<string, unknown>;
    }
  } catch {
    // fall through to undefined
  }
  return undefined;
}

async function createNote(store: NoteStore, req: IncomingMessage, res: ServerResponse): Promise<void> {
  const data = parseObject(await readBody(req));
  if (!data) return fail(res, 400, "Request body must be a JSON object");
  const { title, body } = data;
  if (typeof title !== "string" || title.trim() === "") return fail(res, 400, "title is required");
  send(res, 201, store.create(title, typeof body === "string" ? body : ""));
}

function getNote(store: NoteStore, id: string, res: ServerResponse): void {
  const note = store.get(id);
  if (note) send(res, 200, note);
  else fail(res, 404, "Note not found");
}

async function route(store: NoteStore, req: IncomingMessage, res: ServerResponse): Promise<void> {
  const method = req.method ?? "";
  const path = new URL(req.url ?? "/", "http://localhost").pathname;
  const match = /^\/notes\/([^/]+)$/.exec(path);
  if (path === "/notes" && method === "POST") return createNote(store, req, res);
  if (path === "/notes" && method === "GET") return send(res, 200, store.list());
  if (match && method === "GET") return getNote(store, decodeURIComponent(match[1]), res);
  fail(res, 404, "Not found");
}

export function createServer(store: NoteStore, log: Logger = console.log): Server {
  return createHttpServer((req, res) => {
    res.on("finish", () => log(`${req.method} ${req.url} ${res.statusCode}`));
    route(store, req, res).catch(() => fail(res, 500, "Internal error"));
  });
}
