const base = process.env.BASE_URL ?? "http://localhost:8080";

function check(ok: boolean, message: string): void {
  if (!ok) throw new Error(message);
}

async function checkHealth(): Promise<void> {
  const res = await fetch(`${base}/health`);
  check(res.status === 200, `health: expected 200, got ${res.status}`);
  const data = await res.json();
  check(data?.status === "ok", `health: unexpected body ${JSON.stringify(data)}`);
}

async function createNote(note: { title: string; body: string }): Promise<string> {
  const res = await fetch(`${base}/notes`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify(note),
  });
  check(res.status === 201, `create: expected 201, got ${res.status}`);
  return (await res.json()).id;
}

async function fetchNote(id: string, note: { title: string; body: string }): Promise<void> {
  const res = await fetch(`${base}/notes/${id}`);
  check(res.status === 200, `get: expected 200, got ${res.status}`);
  const got = await res.json();
  check(got.title === note.title && got.body === note.body, "get: title/body mismatch");
}

async function main(): Promise<void> {
  const note = { title: "smoke title", body: "smoke body" };
  await checkHealth();
  const id = await createNote(note);
  await fetchNote(id, note);
  console.log("smoke ok");
}

main().catch((err) => {
  console.error(`smoke failed: ${err instanceof Error ? err.message : String(err)}`);
  process.exit(1);
});
